import json
from unittest.mock import patch

from django.http import HttpResponse

from bloomerp.communication.builtins.voip.builtins.telnyx import TelnyxAdapter
from bloomerp.communication.builtins.voip.controller import adapter_for
from bloomerp.tests.views.communication.voip.telnyx_fixtures import TelnyxFixtures


class TestTelnyxJoinCallComponent(TelnyxFixtures, BloomerpComponentTestCase):
    """Admit Telnyx calls through the existing provider-neutral carrier endpoint."""

    view_name = "components_voip_join_call"

    def reserve(self, scenario: RequestScenario) -> None:
        """Reserve a real call while replacing only the remote token exchange."""
        self.prepare_telnyx()
        self.enterContext(
            patch.object(
                TelnyxAdapter,
                "browser_token",
                return_value='{"token":"jwt","domain":"test.sip.telnyx.com"}',
            )
        )
        self.call = VoIPController(self.normal_user).prepare_call(
            self.chat.pk, "telnyx-join"
        )
        scenario.view_kwargs = {"call_id": self.call.pk}

    def revoke(self, scenario: RequestScenario) -> None:
        """Keep the conversation while removing permission to use its line."""
        self.reserve(scenario)
        self.number.assigned_users.clear()

    def credentials(self, response: HttpResponse) -> bool:
        """Return the common capabilities with an opaque Telnyx reservation reference."""
        data = json.loads(response.content)
        return (
            data["driver"] == "voip"
            and data["carrier_driver"] == "telnyx"
            and data["can_video"] == "false"
            and adapter_for(self.connection).resolve_call_reference(data["call_id"])
            == self.call.pk
            and "never-expose-this" not in response.content.decode()
        )

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Verify that changing the provider requires no new UI or admission endpoint."""
        return [
            RequestScenario(
                name="Telnyx shares the calling contract",
                method="POST",
                user=self.normal_user,
                prepare=self.reserve,
                expected=ExpectedResult(response_validators=self.credentials),
            ),
            RequestScenario(
                name="Telnyx revoked line denied",
                method="POST",
                user=self.normal_user,
                prepare=self.revoke,
                expected=ExpectedResult(status_code=403),
            ),
        ]
